'use strict';

/**
 * Pure decoding logic for Phantom's invisible encodings. No dependency on VS Code, so it
 * can be tested with `node --test`. It mirrors src/phantom/encoding.py, lexer.py and
 * validator.py; test/fixtures.json (generated by scripts/gen_vscode_fixtures.py and checked
 * by the Python test suite) keeps the two implementations in agreement.
 */

const WS_BEGIN = '#:ws:begin';
const WS_END = '#:ws:end';
const ZW_BEGIN = '#:zw:begin';
const ZW_END = '#:zw:end';

// Zero-width payload characters and the two bits each carries (MSB first, four per byte).
const ZW_BITS = new Map([
  [0x200b, 0], // ZERO WIDTH SPACE
  [0x200c, 1], // ZERO WIDTH NON-JOINER
  [0x200d, 2], // ZERO WIDTH JOINER
  [0xfeff, 3], // ZERO WIDTH NO-BREAK SPACE
]);

// Invisible code points that are never valid payload (ZW_REJECTED_CODEPOINTS in grammar.py).
const ZW_REJECTED = new Set([
  0x00ad, 0x034f, 0x061c, 0x115f, 0x1160, 0x17b4, 0x17b5, 0x180e,
  0x2060, 0x2061, 0x2062, 0x2063, 0x2064,
  0x206a, 0x206b, 0x206c, 0x206d, 0x206e, 0x206f,
]);

// Bidirectional controls ("Trojan Source"), _BIDI_CONTROLS in validator.py.
const BIDI = new Set([
  0x200e, 0x200f,
  0x202a, 0x202b, 0x202c, 0x202d, 0x202e,
  0x2066, 0x2067, 0x2068, 0x2069,
]);

const LINE_END = /\r\n|\r|\n/;

function hex(codePoint) {
  return 'U+' + codePoint.toString(16).toUpperCase().padStart(4, '0');
}

function bytesToText(bytes) {
  return new TextDecoder('utf-8', { fatal: true }).decode(Uint8Array.from(bytes));
}

/** Decode whitespace-only lines (8 characters each, space = 0, tab = 1). Throws on bad input. */
function decodeWhitespace(lines) {
  if (lines.length === 0) {
    throw new Error('Whitespace block is empty (no data lines)');
  }
  const bytes = [];
  lines.forEach((raw, index) => {
    const line = raw.replace(/[\r\n]+$/, '');
    if (line.length !== 8) {
      throw new Error(`Whitespace line ${index + 1} has length ${line.length}, expected exactly 8`);
    }
    let value = 0;
    for (const ch of line) {
      if (ch === ' ') {
        value = value << 1;
      } else if (ch === '\t') {
        value = (value << 1) | 1;
      } else {
        throw new Error(`Whitespace line ${index + 1}: invalid character, expected space or tab`);
      }
    }
    bytes.push(value);
  });
  try {
    return bytesToText(bytes);
  } catch (e) {
    throw new Error('Invalid UTF-8 payload in whitespace data');
  }
}

/** Decode a string of zero-width characters (four per byte). Throws on bad input. */
function decodeZeroWidth(text) {
  if (!text) {
    throw new Error('Zero-width data is empty');
  }
  const symbols = [];
  let index = 0;
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (ZW_REJECTED.has(cp)) {
      throw new Error(`Rejected invisible code point at index ${index}: ${hex(cp)}`);
    }
    if (ZW_BITS.has(cp)) {
      symbols.push(ZW_BITS.get(cp));
    }
    index += 1;
  }
  if (symbols.length === 0) {
    throw new Error('No valid zero-width characters found in input');
  }
  if (symbols.length % 4 !== 0) {
    throw new Error(`Incomplete zero-width sequence: ${symbols.length} characters is not a multiple of 4`);
  }
  const bytes = [];
  for (let i = 0; i < symbols.length; i += 4) {
    bytes.push((symbols[i] << 6) | (symbols[i + 1] << 4) | (symbols[i + 2] << 2) | symbols[i + 3]);
  }
  try {
    return bytesToText(bytes);
  } catch (e) {
    throw new Error('Invalid UTF-8 payload in zero-width data');
  }
}

/**
 * Find the hidden blocks in a document.
 * @param {string[]} lines document lines without line terminators
 * @returns {{kind: 'ws'|'zw', beginLine: number, endLine: number, instructions: string[], error: string|null}[]}
 *   line numbers are 0-based; `endLine` is the last line of the document for an unterminated block
 */
function findBlocks(lines) {
  const blocks = [];
  let open = null;
  lines.forEach((line, lineNo) => {
    const stripped = line.trim();
    if (open === null) {
      if (stripped === WS_BEGIN || stripped === ZW_BEGIN) {
        open = { kind: stripped === WS_BEGIN ? 'ws' : 'zw', beginLine: lineNo, data: [] };
      }
      return;
    }
    const closing = open.kind === 'ws' ? WS_END : ZW_END;
    if (stripped === closing) {
      blocks.push(finishBlock(open, lineNo, false));
      open = null;
    } else if (open.kind === 'ws') {
      if ([...line].every((ch) => ch === ' ' || ch === '\t')) {
        open.data.push(line);
      }
    } else {
      const payload = [...line].filter((ch) => {
        const cp = ch.codePointAt(0);
        return ZW_BITS.has(cp) || ZW_REJECTED.has(cp);
      });
      if (payload.length > 0) {
        open.data.push(payload.join(''));
      }
    }
  });
  if (open !== null) {
    blocks.push(finishBlock(open, lines.length - 1, true));
  }
  return blocks;
}

function finishBlock(open, endLine, unterminated) {
  const block = {
    kind: open.kind,
    beginLine: open.beginLine,
    endLine,
    instructions: [],
    error: null,
  };
  if (unterminated) {
    block.error = `Unterminated ${open.kind === 'ws' ? 'whitespace' : 'zero-width'} block`;
    return block;
  }
  if (open.data.length === 0) {
    block.error = `Empty ${open.kind === 'ws' ? 'whitespace' : 'zero-width'} block (no payload)`;
    return block;
  }
  try {
    const decoded = open.kind === 'ws' ? decodeWhitespace(open.data) : decodeZeroWidth(open.data.join(''));
    block.instructions = decoded.split(LINE_END).map((s) => s.trim()).filter((s) => s.length > 0);
  } catch (e) {
    block.error = e.message;
  }
  return block;
}

/**
 * Invisible or bidirectional characters that are not legitimate zero-width payload
 * (the strict audit of `phantom check --strict`).
 * @returns {{line: number, character: number, codePoint: number, bidi: boolean}[]}
 *   `character` is a UTF-16 offset, as VS Code positions use
 */
function findStrayInvisibles(lines, blocks) {
  const insideZw = (lineNo) =>
    blocks.some((b) => b.kind === 'zw' && lineNo > b.beginLine && lineNo < b.endLine + (b.error ? 1 : 0));
  const found = [];
  lines.forEach((line, lineNo) => {
    const allowPayload = insideZw(lineNo);
    let offset = 0;
    for (const ch of line) {
      const cp = ch.codePointAt(0);
      const bidi = BIDI.has(cp);
      const payload = ZW_BITS.has(cp);
      if (bidi || ZW_REJECTED.has(cp) || (payload && !allowPayload)) {
        found.push({ line: lineNo, character: offset, codePoint: cp, bidi });
      }
      offset += ch.length;
    }
  });
  return found;
}

module.exports = {
  WS_BEGIN,
  WS_END,
  ZW_BEGIN,
  ZW_END,
  decodeWhitespace,
  decodeZeroWidth,
  findBlocks,
  findStrayInvisibles,
  hex,
};
